            r, c = r0, c0
            while 0 <= r < h and 0 <= c < w and grid[r][c] != bg:
                cells.append((r, c, grid[r][c]))
                r += 1
                c += dc
            if len(cells) >= 2:
                components.append((dc, cells))
    if not components:
        return out
    longest = max(len(cells) for _, cells in components)
    for dc, cells in components:
        if len(cells) != longest:
            continue
        runs = []
        for cell in cells:
            if not runs or runs[-1][0] != cell[2]:
                runs.append([cell[2], [cell]])
            else:
                runs[-1][1].append(cell)
